
import { Capacitor } from '@capacitor/core';
import { Preferences } from '@capacitor/preferences';

// This file is automatically generated. Do not edit it directly.

/**
 * Storage accepted by Supabase's auth.storage option;
 * localStorage and the editor broker both satisfy it.
 */
export interface PreviewAuthStorage {
  getItem: (key: string) => string | null | Promise<string | null>;
  setItem: (key: string, value: string) => void | Promise<void>;
  removeItem: (key: string) => void | Promise<void>;
}

type BrokerRequestType =
  | 'lovable-preview-auth:get'
  | 'lovable-preview-auth:set'
  | 'lovable-preview-auth:remove';

interface BrokerRequest {
  type: BrokerRequestType;
  requestId: string;
  projectId: string;
  key: string;
  value?: string;
}

interface BrokerReply {
  ok: boolean;
  value: string | null;
}

const RESULT = 'lovable-preview-auth:result';

function readBrokerReply(
  data: unknown,
  requestId: string,
): BrokerReply | null {
  if (typeof data !== 'object' || data === null) return null;
  if (!('type' in data) || data.type !== RESULT) return null;
  if (!('requestId' in data) || data.requestId !== requestId) return null;

  return {
    ok: 'ok' in data && Boolean(data.ok),
    value:
      'value' in data && typeof data.value === 'string'
        ? data.value
        : null,
  };
}

/**
 * On a Lovable preview surface, broker the auth session to the editor
 * over postMessage so the project's preview surfaces share one login.
 * Otherwise, use localStorage.
 */
export function brokeredPreviewStorage(): PreviewAuthStorage | undefined {
  if (typeof window === 'undefined') return undefined;

  const isNative =
    typeof Capacitor !== 'undefined' && Capacitor.isNativePlatform();

  const fallbackStorage = isNative
    ? {
        getItem: async (key: string): Promise<string | null> => {
          let { value } = await Preferences.get({ key });

          if (!value) {
            // Automatic migration from legacy localStorage.
            const legacyValue = localStorage.getItem(key);

            if (legacyValue) {
              console.log(
                '[Auth] Migrating session from localStorage to native Preferences',
              );

              await Preferences.set({
                key,
                value: legacyValue,
              });

              value = legacyValue;
            }
          }

          return value;
        },

        setItem: async (key: string, value: string): Promise<void> => {
          await Preferences.set({ key, value });
          localStorage.setItem(key, value);
        },

        removeItem: async (key: string): Promise<void> => {
          await Preferences.remove({ key });
          localStorage.removeItem(key);
        },
      }
    : localStorage;

  const host = location.hostname;

  const PREVIEW_ZONES = [
    'lovableproject.com',
    'lovableproject-dev.com',
    'lovable.app',
    'gpt-eng.com',
    'gptengineer.run',
  ];

  const onPreviewZone = PREVIEW_ZONES.some(
    (zone) => host === zone || host.endsWith('.' + zone),
  );

  // Read the id only from non-user-controlled host positions.
  // A user-named preview--<name> host cannot smuggle another project's id.
  const UUID =
    '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';

  const projectId = onPreviewZone
    ? (
        new RegExp(
          '^(?:id-preview(?:-[a-z0-9]+)?|project)--(' +
            UUID +
            ')(?:-dev)?(?=\\.|$)',
          'i',
        ).exec(host)?.[1] ??
        new RegExp(
          '^live--(' + UUID + ')(?:-thr_[a-z0-9]+)?(?=\\.|$)',
          'i',
        ).exec(host)?.[1] ??
        new RegExp(
          '^(' + UUID + ')(?=[.-])',
          'i',
        ).exec(host)?.[1]
      )
    : undefined;

  // A detached frame has no parent and not every browser implements
  // ancestorOrigins.
  const parentWindow = window.parent as Window | null;
  const framed = parentWindow !== null && parentWindow !== window;

  if (!projectId || !framed) {
    return isNative ? fallbackStorage : localStorage;
  }

  // Only communicate with a validated editor origin.
  // Session tokens must never reach an untrusted embedder.
  const dev =
    host.endsWith('.lovableproject-dev.com') ||
    host.endsWith('.gpt-eng.com');

  const EDITOR = dev
    ? /^https:\/\/([a-z0-9-]+)\.(lovable\.dev|gptengineer\.app)$|^http:\/\/localhost:3000$/
    : /^https:\/\/([a-z0-9-]+)\.(lovable\.dev|gptengineer\.app)$/;

  const ancestorOrigins = location.ancestorOrigins as
    | DOMStringList
    | undefined;

  const ancestor =
    ancestorOrigins?.[0] ??
    (document.referrer ? new URL(document.referrer).origin : '');

  const editorOrigins =
    ancestor && EDITOR.test(ancestor)
      ? [ancestor]
      : dev
        ? ['https://lovable.dev', 'http://localhost:3000']
        : ['https://lovable.dev'];

  const TIMEOUT = 2000;

  const newId = () =>
    Math.random().toString(36).slice(2) + Date.now().toString(36);

  const request = (
    type: BrokerRequestType,
    key: string,
    value?: string,
  ): Promise<BrokerReply | null> =>
    new Promise((resolve) => {
      const requestId = newId();
      let done = false;

      const finish = (reply: BrokerReply | null) => {
        if (done) return;

        done = true;
        clearTimeout(timer);
        window.removeEventListener('message', onMessage);
        resolve(reply);
      };

      const onMessage = (event: MessageEvent<unknown>) => {
        if (!editorOrigins.includes(event.origin)) return;

        const reply = readBrokerReply(event.data, requestId);

        if (reply) finish(reply);
      };

      window.addEventListener('message', onMessage);

      const timer = setTimeout(() => {
        finish(null);
      }, TIMEOUT);

      const msg: BrokerRequest = {
        type,
        requestId,
        projectId,
        key,
      };

      if (value !== undefined) {
        msg.value = value;
      }

      // Use a trusted target origin for every message.
      for (const origin of editorOrigins) {
        parentWindow.postMessage(msg, origin);
      }
    });

  // The editor may not be listening at the first getItem, so retry once.
  let firstGet = true;
  const RETRY_DELAY = 250;

  // Blocked third-party storage must not break broker reads.
  const readLocal = (key: string): string | null | undefined => {
    try {
      return localStorage.getItem(key);
    } catch {
      return undefined;
    }
  };

  return {
    getItem: async (key: string): Promise<string | null> => {
      if (isNative) {
        return await fallbackStorage.getItem(key);
      }

      // Send the local value with GET so the editor can synchronize it.
      const local = readLocal(key);

      let res = await request(
        'lovable-preview-auth:get',
        key,
        local ?? undefined,
      );

      if (!res && firstGet) {
        await new Promise<void>((resolve) =>
          setTimeout(resolve, RETRY_DELAY),
        );

        res = await request(
          'lovable-preview-auth:get',
          key,
          local ?? undefined,
        );
      }

      firstGet = false;

      // Empty string is the logout tombstone.
      // Null means never synchronized: preserve the local value.
      if (res?.ok && res.value !== null) {
        if (res.value === '') {
          if (local !== undefined && readLocal(key) === local) {
            try {
              localStorage.removeItem(key);
            } catch {
              // Storage may be unavailable.
            }
          }

          return null;
        }

        // Seed this origin so a new tab stays signed in.
        if (local === null && readLocal(key) === null) {
          try {
            localStorage.setItem(key, res.value);
          } catch {
            // Storage full: still return the editor's session.
          }
        }

        return res.value;
      }

      return readLocal(key) ?? null;
    },

    setItem: async (key: string, value: string): Promise<void> => {
      if (isNative) {
        await fallbackStorage.setItem(key, value);
        return;
      }

      localStorage.setItem(key, value);

      const res = await request(
        'lovable-preview-auth:set',
        key,
        value,
      );

      if (
        res?.ok &&
        res.value !== null &&
        localStorage.getItem(key) === value
      ) {
        if (res.value === '') {
          localStorage.removeItem(key);
        } else {
          localStorage.setItem(key, res.value);
        }
      }
    },

    removeItem: async (key: string): Promise<void> => {
      if (isNative) {
        await fallbackStorage.removeItem(key);
        return;
      }

      const local = readLocal(key);

      localStorage.removeItem(key);

      await request(
        'lovable-preview-auth:remove',
        key,
        local ?? undefined,
      );
    },
  };
}
